use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::adapters::{claude, open_agents};
use crate::error::Result;
use crate::manifest::CapabilityManifest;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EmittedFile {
    pub path: String,
    pub hash: String,
}

#[derive(Debug, Clone)]
pub struct PlannedFile {
    pub path: String,
    pub content: Vec<u8>,
}

#[allow(dead_code)]
pub struct ResolvedCapability {
    pub id: String,
    pub capability_type: String,
    pub version: String,
    pub description: String,
    pub source_files: Vec<(String, Vec<u8>)>,
    pub source_dir: PathBuf,
    pub parameters: Option<serde_json::Value>,
    pub implementation: Option<crate::manifest::ImplementationConfig>,
    pub hook: Option<crate::manifest::HookConfig>,
}

pub fn resolve_capability(manifest: &CapabilityManifest) -> Result<ResolvedCapability> {
    let source_files = manifest.read_source_contents_with_names()?;
    Ok(ResolvedCapability {
        id: manifest.id.clone(),
        capability_type: manifest.capability_type.clone(),
        version: manifest.version.clone(),
        description: manifest.description.clone(),
        source_files,
        source_dir: manifest.root.clone(),
        parameters: manifest.parameters.clone(),
        implementation: manifest.implementation.clone(),
        hook: manifest.hook.clone(),
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AdapterKind {
    OpenAgents,
    Claude,
}

impl AdapterKind {
    pub fn id(&self) -> &'static str {
        match self {
            Self::OpenAgents => open_agents::ID,
            Self::Claude => claude::ID,
        }
    }

    pub fn display_name(&self) -> &'static str {
        match self {
            Self::OpenAgents => open_agents::DISPLAY_NAME,
            Self::Claude => claude::DISPLAY_NAME,
        }
    }

    pub fn all() -> Vec<Self> {
        vec![Self::OpenAgents, Self::Claude]
    }

    pub fn from_id(id: &str) -> Option<Self> {
        match id {
            open_agents::ID => Some(Self::OpenAgents),
            "codex" => Some(Self::OpenAgents),
            claude::ID => Some(Self::Claude),
            "claude-code" => Some(Self::Claude),
            _ => None,
        }
    }

    pub fn supports(&self, capability_type: &str) -> bool {
        match self {
            Self::OpenAgents => open_agents::supports(capability_type),
            Self::Claude => claude::supports(capability_type),
        }
    }

    pub fn plan(
        &self,
        capability: &ResolvedCapability,
        repo_root: &Path,
    ) -> Result<Vec<PlannedFile>> {
        match self {
            Self::OpenAgents => open_agents::plan(capability, repo_root),
            Self::Claude => claude::plan(capability, repo_root),
        }
    }

    pub fn remove(&self, primitive_id: &str, repo_root: &Path) -> Result<()> {
        match self {
            Self::OpenAgents => open_agents::remove(primitive_id, repo_root),
            Self::Claude => claude::remove(primitive_id, repo_root),
        }
    }

    #[allow(dead_code)]
    pub fn detect(&self, repo_root: &Path) -> bool {
        match self {
            Self::OpenAgents => open_agents::detect(repo_root),
            Self::Claude => claude::detect(repo_root),
        }
    }

    pub fn kinds_supported(&self) -> &[&'static str] {
        match self {
            Self::OpenAgents => open_agents::SUPPORTED_TYPES,
            Self::Claude => claude::SUPPORTED_TYPES,
        }
    }

    pub fn supported_agents(&self) -> &[&'static str] {
        match self {
            Self::OpenAgents => open_agents::SUPPORTED_AGENTS,
            Self::Claude => claude::SUPPORTED_AGENTS,
        }
    }

    pub fn supported_events(&self) -> &[&'static str] {
        match self {
            Self::OpenAgents => open_agents::SUPPORTED_EVENTS,
            Self::Claude => claude::SUPPORTED_EVENTS,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn from_id_returns_open_agents_for_codex_alias() {
        assert_eq!(AdapterKind::from_id("codex"), Some(AdapterKind::OpenAgents));
        assert_eq!(AdapterKind::from_id("open-agents"), Some(AdapterKind::OpenAgents));
    }

    #[test]
    fn from_id_returns_claude_for_claude_code_alias() {
        assert_eq!(AdapterKind::from_id("claude-code"), Some(AdapterKind::Claude));
        assert_eq!(AdapterKind::from_id("claude"), Some(AdapterKind::Claude));
    }

    #[test]
    fn from_id_returns_none_for_unknown() {
        assert_eq!(AdapterKind::from_id("nonexistent"), None);
    }

    #[test]
    fn all_returns_two_adapters() {
        let all = AdapterKind::all();
        assert_eq!(all.len(), 2);
    }

    #[test]
    fn display_name_not_empty() {
        for a in AdapterKind::all() {
            assert!(!a.display_name().is_empty());
            assert!(!a.id().is_empty());
        }
    }
}

use std::path::Path;

use crate::adapter::{PlannedFile, ResolvedCapability};
use crate::error::{CoralError, Result};
use crate::lockfile;

pub const ID: &str = "claude";
pub const DISPLAY_NAME: &str = "Claude";
pub const SUPPORTED_TYPES: &[&str] = &["skill", "tool", "hook"];

pub const SUPPORTED_AGENTS: &[&str] = &["Claude Code"];

pub const SUPPORTED_EVENTS: &[&str] = &[
    "before_finish",
    "post_tool_execution",
];

pub fn supports(capability_type: &str) -> bool {
    SUPPORTED_TYPES.contains(&capability_type)
}

pub fn plan(capability: &ResolvedCapability, repo_root: &Path) -> Result<Vec<PlannedFile>> {
    match capability.capability_type.as_str() {
        "tool" => plan_tool(capability, repo_root),
        "hook" => plan_hook(capability, repo_root),
        _ => plan_skill(capability, repo_root),
    }
}

fn plan_skill(capability: &ResolvedCapability, repo_root: &Path) -> Result<Vec<PlannedFile>> {
    if capability.source_files.is_empty() {
        return Err(CoralError::new("no source files to emit"));
    }

    let mut files = Vec::new();
    for (rel_path, content) in &capability.source_files {
        let target_path = repo_root
            .join(".claude")
            .join("skills")
            .join(&capability.id)
            .join(rel_path);

        files.push(PlannedFile {
            path: lockfile::relative_or_absolute_fs(&target_path, repo_root),
            content: content.clone(),
        });
    }
    Ok(files)
}

fn plan_tool(capability: &ResolvedCapability, repo_root: &Path) -> Result<Vec<PlannedFile>> {
    let mut files = Vec::new();

    for (rel_path, content) in &capability.source_files {
        let target_path = repo_root
            .join(".claude")
            .join("tools")
            .join(&capability.id)
            .join(rel_path);

        files.push(PlannedFile {
            path: lockfile::relative_or_absolute_fs(&target_path, repo_root),
            content: content.clone(),
        });
    }

    if capability.source_files.is_empty() {
        let placeholder = repo_root
            .join(".claude")
            .join("tools")
            .join(&capability.id)
            .join(".gitkeep");
        files.push(PlannedFile {
            path: lockfile::relative_or_absolute_fs(&placeholder, repo_root),
            content: vec![],
        });
    }

    Ok(files)
}

fn plan_hook(capability: &ResolvedCapability, repo_root: &Path) -> Result<Vec<PlannedFile>> {
    let hook_cfg = capability.hook.as_ref().ok_or_else(|| {
        CoralError::new("hook capability requires [hook] section")
    })?;

    let target_path = repo_root
        .join(".claude")
        .join("hooks")
        .join(&capability.id)
        .join("hook.json");

    let content = serde_json::json!({
        "event": hook_cfg.event,
        "command": hook_cfg.command,
        "working_directory": hook_cfg.working_directory,
    });

    Ok(vec![PlannedFile {
        path: lockfile::relative_or_absolute_fs(&target_path, repo_root),
        content: serde_json::to_string_pretty(&content)?.into_bytes(),
    }])
}

pub fn remove(primitive_id: &str, repo_root: &Path) -> Result<()> {
    remove_dir(repo_root, ".claude", "skills", primitive_id)?;
    remove_dir(repo_root, ".claude", "tools", primitive_id)?;
    remove_dir(repo_root, ".claude", "hooks", primitive_id)?;

    let mcp_path = repo_root.join(".mcp.json");
    super::mcp_remove_tool(repo_root, &mcp_path, primitive_id)?;

    Ok(())
}

fn remove_dir(repo_root: &Path, base: &str, kind: &str, primitive_id: &str) -> Result<()> {
    let dir = repo_root.join(base).join(kind).join(primitive_id);

    if dir.exists() {
        std::fs::remove_dir_all(&dir)?;
    }

    let kind_dir = dir.parent().expect("kind dir should have parent");
    if kind_dir.exists() {
        let mut rd = match std::fs::read_dir(kind_dir) {
            Ok(rd) => rd,
            Err(_) => return Ok(()),
        };
        if rd.next().is_none() {
            std::fs::remove_dir(kind_dir)?;
        }
    }

    let base_dir = kind_dir.parent().expect("base dir should have parent");
    if base_dir.exists() {
        let mut rd = match std::fs::read_dir(base_dir) {
            Ok(rd) => rd,
            Err(_) => return Ok(()),
        };
        if rd.next().is_none() {
            std::fs::remove_dir(base_dir)?;
        }
    }

    Ok(())
}

#[allow(dead_code)]
pub fn detect(repo_root: &Path) -> bool {
    repo_root.join(".claude").exists() || repo_root.join("CLAUDE.md").exists()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn supports_returns_true_for_known_types() {
        assert!(supports("skill"));
        assert!(supports("tool"));
        assert!(supports("hook"));
    }

    #[test]
    fn supports_returns_false_for_unknown() {
        assert!(!supports("unknown"));
    }

    #[test]
    fn constants_are_not_empty() {
        assert!(!ID.is_empty());
        assert!(!DISPLAY_NAME.is_empty());
        assert!(!SUPPORTED_EVENTS.is_empty());
    }
}

pub mod claude;
