    }

    #[test]
    fn write_and_read_roundtrip() {
        let tmp = TempDir::new().unwrap();
        let path = tmp.path().join("roundtrip.json");
        let mut lf = Lockfile {
            version: 2,
            capabilities: BTreeMap::new(),
        };
        lf.capabilities.insert(
