                source_path: "".into(),
                targets: BTreeMap::new(),
                source: None,
                scope: "project".into(),
            },
        );
        write_lockfile_at(&path, &lf).unwrap();
        let read = read_lockfile_at(&path).unwrap();
        assert_eq!(read.capabilities.len(), 1);
    }

