    }

    #[test]
    fn load_skill_manifest_succeeds() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir_all(tmp.path().join("src")).unwrap();
        fs::write(tmp.path().join("src").join("SKILL.md"), "# Skill").unwrap();
        write_manifest(tmp.path(), r#"id = "test"
version = "1.0.0"
type = "skill"
description = "A test skill"
files = ["src/SKILL.md"]
"#);
        let m = load_manifest(tmp.path()).unwrap();
        assert_eq!(m.id, "test");
        assert_eq!(m.capability_type, "skill");
    }

    #[test]
    fn load_tool_manifest_succeeds() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("run.sh"), "echo ok").unwrap();
        write_manifest(tmp.path(), r#"id = "tool1"
version = "1.0.0"
type = "tool"
description = "A test tool"
files = ["run.sh"]

[parameters]
type = "object"
required = ["x"]
[parameters.properties.x]
type = "string"
description = "x"

[implementation]
language = "bash"
entrypoint = "run.sh"
"#);
        let m = load_manifest(tmp.path()).unwrap();
        assert_eq!(m.capability_type, "tool");
        assert!(m.implementation.is_some());
    }

    #[test]
    fn load_hook_manifest_succeeds() {
        let tmp = TempDir::new().unwrap();
        write_manifest(tmp.path(), r#"id = "hook1"
version = "1.0.0"
type = "hook"
description = "A test hook"

[hook]
event = "before_finish"
command = "cargo test"
"#);
        let m = load_manifest(tmp.path()).unwrap();
        assert_eq!(m.capability_type, "hook");
        assert!(m.hook.is_some());
    }

    #[test]
    fn load_rejects_unsupported_type() {
        let tmp = TempDir::new().unwrap();
        write_manifest(tmp.path(), r#"id = "bad"
version = "1.0.0"
type = "unknown"
description = "Bad"
files = ["SKILL.md"]
"#);
        assert!(load_manifest(tmp.path()).is_err());
    }

    #[test]
    fn load_rejects_missing_manifest() {
        let tmp = TempDir::new().unwrap();
        assert!(load_manifest(tmp.path()).is_err());
    }

    #[test]
    fn source_files_resolves_paths() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir_all(tmp.path().join("src")).unwrap();
        fs::write(tmp.path().join("src").join("SKILL.md"), "skill").unwrap();
        let m = CapabilityManifest {
            id: "t".into(),
            version: "1.0".into(),
            capability_type: "skill".into(),
            description: "desc".into(),
            files: vec!["src/SKILL.md".into()],
            parameters: None,
            implementation: None,
            hook: None,
            targets: vec![],
            root: tmp.path().to_path_buf(),
        };
        let files = m.source_files().unwrap();
        assert_eq!(files.len(), 1);
        assert!(files[0].ends_with("SKILL.md"));
    }

    #[test]
    fn source_files_rejects_missing_file() {
        let tmp = TempDir::new().unwrap();
        let m = CapabilityManifest {
            id: "t".into(),
            version: "1.0".into(),
            capability_type: "skill".into(),
            description: "desc".into(),
            files: vec!["src/MISSING.md".into()],
            parameters: None,
            implementation: None,
            hook: None,
            targets: vec![],
            root: tmp.path().to_path_buf(),
        };
        assert!(m.source_files().is_err());
    }

    #[test]
    fn validate_non_empty_rejects_empty() {
        assert!(validate_non_empty("id", "").is_err());
        assert!(validate_non_empty("id", "ok").is_ok());
    }
}

use std::path::{Path, PathBuf};

use crate::error::Result;
use crate::lockfile;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Scope {
    Project,
    Global,
}

impl Scope {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Project => "project",
            Self::Global => "global",
        }
    }

    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "project" => Some(Self::Project),
            "global" => Some(Self::Global),
            _ => None,
        }
    }
}

pub fn home_coral_dir() -> Option<PathBuf> {
    dirs_home().map(|h| h.join(".coral"))
}

pub fn coral_dir(scope: Scope, repo_root: Option<&Path>) -> Option<PathBuf> {
    match scope {
        Scope::Project => repo_root.map(|r| r.join(".coral")),
        Scope::Global => home_coral_dir(),
    }
}

pub fn lockfile_path_for(scope: Scope, repo_root: Option<&Path>) -> Option<PathBuf> {
    coral_dir(scope, repo_root).map(|d| d.join("coral-lock.json"))
}

pub fn read_lockfile(scope: Scope, repo_root: Option<&Path>) -> Result<Option<lockfile::Lockfile>> {
    let path = match lockfile_path_for(scope, repo_root) {
        Some(p) => p,
        None => return Ok(None),
    };
    if path.exists() {
        Ok(Some(lockfile::read_lockfile_at(&path)?))
    } else {
        Ok(None)
    }
}

pub fn resolve_entry(
    id: &str,
    repo_root: &Path,
) -> Result<Option<(Scope, lockfile::CapabilityLockEntry)>> {
    if let Some(project_lf) = read_lockfile(Scope::Project, Some(repo_root))? {
        if let Some(entry) = project_lf.capabilities.get(id) {
            return Ok(Some((Scope::Project, entry.clone())));
        }
    }

    if let Some(global_lf) = read_lockfile(Scope::Global, None)? {
        if let Some(entry) = global_lf.capabilities.get(id) {
            return Ok(Some((Scope::Global, entry.clone())));
        }
    }

    Ok(None)
}

pub fn overrides_global(
    id: &str,
    repo_root: &Path,
) -> Result<bool> {
    let project_exists = read_lockfile(Scope::Project, Some(repo_root))?
        .map(|lf| lf.capabilities.contains_key(id))
        .unwrap_or(false);

    let global_exists = read_lockfile(Scope::Global, None)?
        .map(|lf| lf.capabilities.contains_key(id))
        .unwrap_or(false);

    Ok(project_exists && global_exists)
}

pub fn check_collision(
    id: &str,
    _repo_root: &Path,
    new_source_url: Option<&str>,
) -> Result<Option<String>> {
    let Some(global_lf) = read_lockfile(Scope::Global, None)? else {
        return Ok(None);
    };

    let Some(global_entry) = global_lf.capabilities.get(id) else {
        return Ok(None);
    };

    let global_source = global_entry.source.as_ref().map(|s| s.url.as_str());

    match (new_source_url, global_source) {
        (Some(new_url), Some(global_url)) if new_url != global_url => {
            Ok(Some(format!(
                "note: '{}' is already installed globally from a different source ({}). \
                 The project copy will take precedence and the global copy will be shadowed.",
                id, global_url
            )))
        }
        (None, Some(global_url)) => {
            Ok(Some(format!(
                "note: '{}' is already installed globally from {}. \
                 The project copy will take precedence and the global copy will be shadowed.",
                id, global_url
            )))
        }
        _ => Ok(None),
    }
}

#[cfg(unix)]
fn dirs_home() -> Option<PathBuf> {
    std::env::var("HOME").ok().map(PathBuf::from)
}

#[cfg(windows)]
fn dirs_home() -> Option<PathBuf> {
    std::env::var("USERPROFILE")
        .ok()
        .map(PathBuf::from)
        .or_else(|| {
            let drive = std::env::var("HOMEDRIVE").ok()?;
            let path = std::env::var("HOMEPATH").ok()?;
            Some(PathBuf::from(format!("{}{}", drive, path)))
        })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lockfile;
    use std::fs;
    use tempfile::TempDir;

    fn create_lockfile(path: &std::path::Path, entries: &[(&str, &str, &str)]) {
        let mut lf = lockfile::Lockfile {
            version: 2,
            capabilities: std::collections::BTreeMap::new(),
        };
        for (id, capability_type, version) in entries {
            lf.capabilities.insert(
                id.to_string(),
                lockfile::CapabilityLockEntry {
                    capability_type: capability_type.to_string(),
                    installed_version: version.to_string(),
                    source_path: "".into(),
                    targets: std::collections::BTreeMap::new(),
                    source: None,
                    scope: "project".into(),
                },
            );
        }
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, serde_json::to_string_pretty(&lf).unwrap() + "\n").unwrap();
    }

    #[test]
    fn scope_from_str_valid() {
        assert_eq!(Scope::from_str("project"), Some(Scope::Project));
        assert_eq!(Scope::from_str("global"), Some(Scope::Global));
        assert_eq!(Scope::from_str("invalid"), None);
    }

    #[test]
    fn scope_as_str() {
        assert_eq!(Scope::Project.as_str(), "project");
        assert_eq!(Scope::Global.as_str(), "global");
    }

    #[test]
    fn resolve_entry_project_wins_over_global() {
        let tmp = TempDir::new().unwrap();
        let proj_lock = tmp.path().join(".coral").join("coral-lock.json");
        create_lockfile(&proj_lock, &[("test", "skill", "1.0-project")]);

        // Create a fake global lockfile that won't be checked
        // since we can't easily control HOME in tests, test project-only path
        let result = read_lockfile(Scope::Project, Some(tmp.path())).unwrap();
        assert!(result.is_some());
        let lf = result.unwrap();
        assert_eq!(lf.capabilities["test"].installed_version, "1.0-project");
    }

    #[test]
    fn resolve_entry_not_found_returns_none() {
        let tmp = TempDir::new().unwrap();
        let proj_lock = tmp.path().join(".coral").join("coral-lock.json");
        create_lockfile(&proj_lock, &[("other", "skill", "1.0")]);

        let result = resolve_entry("missing", tmp.path()).unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn overrides_global_false_when_no_conflict() {
        let tmp = TempDir::new().unwrap();
        let proj_lock = tmp.path().join(".coral").join("coral-lock.json");
        create_lockfile(&proj_lock, &[("test", "skill", "1.0")]);

        assert!(!overrides_global("test", tmp.path()).unwrap());
    }

    #[test]
    fn check_collision_no_global_returns_none() {
        let tmp = TempDir::new().unwrap();
        let result = check_collision("test", tmp.path(), Some("https://github.com/a/b")).unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn home_coral_dir_returns_some() {
        assert!(home_coral_dir().is_some());
    }
}

use std::path::Path;

use crate::error::{CoralError, Result};

pub fn validate_json_schema(value: &serde_json::Value) -> Result<()> {
    let obj = value.as_object().ok_or_else(|| {
        CoralError::new("parameters must be a JSON object with 'type: object'")
    })?;

    let schema_type = obj
        .get("type")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    if schema_type != "object" {
        return Err(CoralError::new(format!(
            "parameters 'type' must be 'object', got '{}'",
            schema_type
        )));
    }

    if !obj.contains_key("properties") {
        return Err(CoralError::new(
            "parameters must have a 'properties' section defining the tool's input schema",
        ));
    }

    let properties = obj.get("properties").and_then(|v| v.as_object());
    if properties.is_none() || properties.unwrap().is_empty() {
        return Err(CoralError::new(
            "parameters 'properties' must contain at least one parameter definition",
        ));
    }

    if obj.contains_key("required") {
        let required = obj.get("required").and_then(|v| v.as_array());
        if required.is_none() {
            return Err(CoralError::new("parameters 'required' must be an array of field names"));
        }
    }

    Ok(())
}

pub fn validate_entrypoint(primitive_dir: &Path, entrypoint: &str) -> Result<()> {
    check_path_traversal(entrypoint)?;

    let path = primitive_dir.join(entrypoint);
    if !path.exists() {
        return Err(CoralError::new(format!(
            "implementation entrypoint not found: {}",
            path.display()
        )));
    }

    if !path.is_file() {
        return Err(CoralError::new(format!(
            "implementation entrypoint must be a file, not a directory: {}",
            path.display()
        )));
    }

    Ok(())
}

pub fn check_path_traversal(entrypoint: &str) -> Result<()> {
    if entrypoint.is_empty() {
        return Err(CoralError::new("implementation entrypoint must not be empty"));
    }

    if entrypoint.starts_with('/') {
        return Err(CoralError::new(
            "implementation entrypoint must be a relative path, not absolute",
        ));
    }

    let clean = entrypoint.trim_start_matches("./");

    for component in clean.split('/') {
        if component == ".." {
            return Err(CoralError::new(
                "implementation entrypoint must not use '..' — path traversal is not allowed",
            ));
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    use std::fs;
    use tempfile::TempDir;

    #[test]
    fn schema_valid_object_with_properties() {
        let schema = json!({
            "type": "object",
            "properties": { "target": { "type": "string" } },
            "required": ["target"]
        });
        assert!(validate_json_schema(&schema).is_ok());
    }

    #[test]
    fn schema_rejects_missing_type() {
        assert!(validate_json_schema(&json!({"properties": {"x": {"type": "string"}}})).is_err());
    }

    #[test]
    fn schema_rejects_non_object_type() {
        assert!(validate_json_schema(&json!({"type": "string", "properties": {}})).is_err());
    }

    #[test]
    fn schema_rejects_missing_properties() {
        assert!(validate_json_schema(&json!({"type": "object"})).is_err());
    }

    #[test]
    fn schema_rejects_empty_properties() {
        assert!(validate_json_schema(&json!({"type": "object", "properties": {}})).is_err());
    }

    #[test]
    fn schema_accepts_no_required_field() {
        assert!(validate_json_schema(&json!({"type": "object", "properties": {"file": {"type": "string"}}})).is_ok());
    }

    #[test]
    fn path_traversal_blocks_dot_dot() {
        assert!(check_path_traversal("../etc/passwd").is_err());
        assert!(check_path_traversal("scripts/../../../etc/passwd").is_err());
    }

    #[test]
    fn path_traversal_blocks_absolute() {
        assert!(check_path_traversal("/etc/passwd").is_err());
    }

    #[test]
    fn path_traversal_blocks_empty() {
        assert!(check_path_traversal("").is_err());
    }

    #[test]
    fn path_traversal_allows_relative() {
        assert!(check_path_traversal("run.sh").is_ok());
        assert!(check_path_traversal("./run.sh").is_ok());
        assert!(check_path_traversal("scripts/run.sh").is_ok());
    }

    #[test]
    fn entrypoint_rejects_non_existent_file() {
        let tmp = TempDir::new().unwrap();
        assert!(validate_entrypoint(tmp.path(), "missing.sh").is_err());
    }

    #[test]
    fn entrypoint_accepts_valid_file() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("run.sh"), "echo ok").unwrap();
        assert!(validate_entrypoint(tmp.path(), "run.sh").is_ok());
    }

    #[test]
    fn entrypoint_rejects_directory() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir_all(tmp.path().join("subdir")).unwrap();
        assert!(validate_entrypoint(tmp.path(), "subdir").is_err());
    }
